/**
 * AccountTriggerHandler
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-04
 * @group TriggerHandler
 */

public with sharing class AccountTriggerHandler extends TriggerHandler {
    protected override void afterInsert() {
        this.handleAfter('AccountCreated');
    }

    protected override void afterUpdate() {
        this.handleAfter('AccountUpdated');
    }

    private void handleAfter(String eventType) {
        new AccountAzureEvent(this.newList, this.oldMap, eventType).emitEvents();
    }
}

