     1→/**
     2→ * AzureEventAccountDTO
     3→ *
     4→ * @author Nick Morozov (nmorozov@corraogroup.com)
     5→ * @since 2025-12-04
     6→ */
     7→
     8→public with sharing abstract class AzureEvent {
     9→    public transient final List<SObject> newList;
    10→    protected transient final Map<Id, SObject> oldMap;
    11→
    12→    protected transient Map<Id, EventGridDTO> payloadsByContextIds;
    13→
    14→    public AzureEvent() {
    15→        this.newList = new List<SObject>();
    16→        this.oldMap = new Map<Id, SObject>();
    17→        this.payloadsByContextIds = new Map<Id, EventGridDTO>();
    18→    }
    19→
    20→    public AzureEvent(List<SObject> newList, Map<Id, SObject> oldMap) {
    21→        this.newList = newList;
    22→        this.oldMap = oldMap;
    23→
    24→        this.payloadsByContextIds = new Map<Id, EventGridDTO>();
    25→
    26→        Map<Id, Object> queriedData = this.queryData();
    27→        Map<Id, Object> validData = this.validateData(queriedData);
    28→
    29→        this.mapData(validData);
    30→    }
    31→
    32→    public EventGridDTO getPayload(Id contextId) {
    33→        return this.payloadsByContextIds.get(contextId);
    34→    }
    35→
    36→    public void emitEvents() {
    37→        if (this.payloadsByContextIds.isEmpty()) {
    38→            return;
    39→        }
    40→
    41→        String contextObjectName = new List<Id>(this.payloadsByContextIds.keySet()).get(0).getSobjectType().getDescribe().getName();
    42→        List<Azure_Event__c> eventsToInsert = new List<Azure_Event__c>();
    43→
    44→        for (Id contextId : this.payloadsByContextIds.keySet()) {
    45→            EventGridDTO event = this.payloadsByContextIds.get(contextId);
    46→
    47→            if (event != null) {
    48→                eventsToInsert.add(new Azure_Event__c(
    49→                    SF_Record_Id__c = contextId,
    50→                    Object_Name__c = contextObjectName,
    51→                    Event_Type__c = this.getEventType(),
    52→                    Payload__c = event.toJSON()
    53→                ));
    54→            }
    55→        }
    56→
    57→        if (!eventsToInsert.isEmpty()) {
    58→            insert eventsToInsert;
    59→        }
    60→    }
    61→
    62→    @TestVisible
    63→    protected abstract Map<Id, Object> queryData();
    64→
    65→    @TestVisible
    66→    protected abstract Map<Id, Object> validateData(Map<Id, Object> queriedDataByContextId);
    67→
    68→    protected abstract String getType();
    69→
    70→    protected abstract String getSubject();
    71→
    72→    protected abstract String getEventType();
    73→
    74→    private void mapData(Map<Id, Object> validatedDataByContextId) {
    75→        for (Id contextId : validatedDataByContextId.keySet()) {
    76→            DataProperty dto = (DataProperty) Type.forName(this.getType()).newInstance();
    77→            Object datum = validatedDataByContextId.get(contextId);
    78→            dto.mapDatum(datum);
    79→            EventGridDTO eventDto = new EventGridDTO(contextId, dto, this.getSubject(), this.getEventType());
    80→            this.payloadsByContextIds.put(contextId, eventDto);
    81→        }
    82→    }
    83→
    84→    public with sharing class EventGridDTO {
    85→        private final transient Id contextId;
    86→
    87→        @AuraEnabled
    88→        public String topic; // Not required
    89→
    90→        @AuraEnabled
    91→        public String subject;
    92→
    93→        @AuraEnabled
    94→        public String id;
    95→
    96→        @AuraEnabled
    97→        public String eventType;
    98→
    99→        @AuraEnabled
   100→        public String eventTime;
   101→
   102→        @AuraEnabled
   103→        public DataProperty dataX; // data is not allowed as variable name
   104→
   105→        @AuraEnabled
   106→        public String dataVersion;
   107→
   108→        @AuraEnabled
   109→        public String metadataVersion; // Not required
   110→
   111→        public EventGridDTO(Id contextId, DataProperty dto, String subject, String eventType) {
   112→            this.contextId = contextId;
   113→            this.id = String.valueOf(contextId) + String.valueOf(System.now().getTime()) + String.valueOf(Crypto.getRandomLong());
   114→            this.subject = subject + String.valueOf(contextId);
   115→            this.eventTime = System.now().formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
   116→            this.eventType = eventType;
   117→            this.dataVersion = dto.getVersion();
   118→            this.dataX = dto;
   119→        }
   120→
   121→        public String toJSON() {
   122→            return JSON.serialize(this)?.replace('dataX', 'data').replace('newX', 'new');
   123→        }
   124→    }
   125→
   126→    public with sharing abstract class DataProperty {
