/**
 * AzureEventAccountDTO
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-04
 */

public with sharing abstract class AzureEvent {
    public transient final List<SObject> newList;
    protected transient final Map<Id, SObject> oldMap;

    protected transient Map<Id, EventGridDTO> payloadsByContextIds;

    public AzureEvent() {
        this.newList = new List<SObject>();
        this.oldMap = new Map<Id, SObject>();
        this.payloadsByContextIds = new Map<Id, EventGridDTO>();
    }

    public AzureEvent(List<SObject> newList, Map<Id, SObject> oldMap) {
        this.newList = newList;
        this.oldMap = oldMap;

        this.payloadsByContextIds = new Map<Id, EventGridDTO>();

        Map<Id, Object> queriedData = this.queryData();
        Map<Id, Object> validData = this.validateData(queriedData);

        this.mapData(validData);
    }

    public EventGridDTO getPayload(Id contextId) {
        return this.payloadsByContextIds.get(contextId);
    }

    public void emitEvents() {
        if (this.payloadsByContextIds.isEmpty()) {
            return;
        }

        String contextObjectName = new List<Id>(this.payloadsByContextIds.keySet()).get(0).getSobjectType().getDescribe().getName();
        List<Azure_Event__c> eventsToInsert = new List<Azure_Event__c>();

        for (Id contextId : this.payloadsByContextIds.keySet()) {
            EventGridDTO event = this.payloadsByContextIds.get(contextId);

            if (event != null) {
                eventsToInsert.add(new Azure_Event__c(
                    SF_Record_Id__c = contextId,
                    Object_Name__c = contextObjectName,
                    Event_Type__c = this.getEventType(),
                    Payload__c = event.toJSON()
                ));
            }
        }

        if (!eventsToInsert.isEmpty()) {
            insert eventsToInsert;
        }
    }

    @TestVisible
    protected abstract Map<Id, Object> queryData();

    @TestVisible
    protected abstract Map<Id, Object> validateData(Map<Id, Object> queriedDataByContextId);

    protected abstract String getType();

    protected abstract String getSubject();

    protected abstract String getEventType();

    private void mapData(Map<Id, Object> validatedDataByContextId) {
        for (Id contextId : validatedDataByContextId.keySet()) {
            DataProperty dto = (DataProperty) Type.forName(this.getType()).newInstance();
            Object datum = validatedDataByContextId.get(contextId);
            dto.mapDatum(datum);
            EventGridDTO eventDto = new EventGridDTO(contextId, dto, this.getSubject(), this.getEventType());
            this.payloadsByContextIds.put(contextId, eventDto);
        }
    }

    public with sharing class EventGridDTO {
        private final transient Id contextId;

        @AuraEnabled
        public String topic; // Not required

        @AuraEnabled
        public String subject;

        @AuraEnabled
        public String id;

        @AuraEnabled
        public String eventType;

        @AuraEnabled
        public String eventTime;

        @AuraEnabled
        public DataProperty dataX; // data is not allowed as variable name

        @AuraEnabled
        public String dataVersion;

        @AuraEnabled
        public String metadataVersion; // Not required

        public EventGridDTO(Id contextId, DataProperty dto, String subject, String eventType) {
            this.contextId = contextId;
            this.id = String.valueOf(contextId) + String.valueOf(System.now().getTime()) + String.valueOf(Crypto.getRandomLong());
            this.subject = subject + String.valueOf(contextId);
            this.eventTime = System.now().formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
            this.eventType = eventType;
            this.dataVersion = dto.getVersion();
            this.dataX = dto;
        }

        public String toJSON() {
            return JSON.serialize(this)?.replace('dataX', 'data').replace('newX', 'new');
        }
    }

    public with sharing abstract class DataProperty {
        public abstract void mapDatum(Object validatedDatum);
        public abstract String getVersion();
    }
}

